<?php
namespace App\Domain\Audit\Services;
use App\Models\AuditLog;use App\Models\User;use Illuminate\Support\Facades\DB;use Illuminate\Support\Str;use RuntimeException;
class AuditRecorder{private array $secretKeys=['password','password_confirmation','remember_token','token','secret','mfa_secret','api_key','database_password'];public function record(string $action,string $module,string $result='SUCCESS',?User $actor=null,array $data=[]):AuditLog{$actor??=auth()->user();$partition=now()->format('Ymd').'-'.str_pad((string)((($actor?->id??0)%16)),2,'0',STR_PAD_LEFT);return DB::transaction(function()use($action,$module,$result,$actor,$data,$partition){$previous=AuditLog::where('chain_partition',$partition)->lockForUpdate()->latest('id')->value('event_hash');$payload=['event_ulid'=>(string)Str::ulid(),'occurred_at'=>now()->toISOString(),'actor_id'=>$actor?->id,'actor_username_snapshot'=>$actor?->username,'actor_roles_snapshot'=>$actor?->getRoleNames()->values()->all()??[],'action'=>$action,'module'=>$module,'subject_type'=>$data['subject_type']??null,'subject_ulid'=>$data['subject_ulid']??null,'document_id'=>$data['document_id']??null,'barcode_value'=>$data['barcode_value']??null,'old_values'=>$this->redact($data['old_values']??null),'new_values'=>$this->redact($data['new_values']??null),'ip_address'=>request()->ip(),'user_agent'=>Str::limit((string)request()->userAgent(),1000,''),'request_id'=>request()->attributes->get('request_id'),'result'=>$result,'failure_reason'=>$data['failure_reason']??null,'context'=>$this->redact($data['context']??null),'chain_partition'=>$partition,'previous_hash'=>$previous];$canonical=json_encode($payload,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR);$key=(string)config('app.dms_audit_hmac_key',env('DMS_AUDIT_HMAC_KEY'));if($key==='')throw new RuntimeException('DMS audit HMAC key is not configured.');$payload['event_hash']=hash_hmac('sha256',($previous??'GENESIS').'|'.$canonical,$key);$payload['occurred_at']=now();return AuditLog::create($payload);});}private function redact(?array $data):?array{if($data===null)return null;foreach($data as $k=>$v){if(in_array(strtolower((string)$k),$this->secretKeys,true))$data[$k]='[REDACTED]';elseif(is_array($v))$data[$k]=$this->redact($v);}return $data;}}
